// This file was generated by Slater.app - buttons.js


gsap.registerPlugin(SplitText);

function initButton099() {
  const buttons = document.querySelectorAll('[data-button-099]');
  if (buttons.length === 0) return;

  const BASE_STAGGER = 0.018; // seconds, used up to the threshold
  const CHAR_THRESHOLD = 10; // char count where the cap kicks in
  const MAX_SWEEP = (CHAR_THRESHOLD - 1) * BASE_STAGGER; // 0.162s total stagger sweep

  buttons.forEach((element) => {
    const text = element.querySelector('[data-button-099-text]');
    const accessibleText = text.textContent.trim();

    const splitText = new SplitText(element, {
      type: 'chars',
      tag: 'span',
      charsClass: 'button-099__split-char',
      propIndex: true,
      aria: 'none',
    });

    element.setAttribute('aria-label', accessibleText);
    gsap.set(splitText.chars, { display: 'inline-block' });

    // Re-index --char per content group so the default and hover
    // sequences both start at 1, then let icons continue the sequence
    const groups = element.querySelectorAll('.button-099__content');
    const scopes = groups.length ? groups : [element];
    let maxChars = 0;

    scopes.forEach((group) => {
      let index = 0;
      group.querySelectorAll('.button-099__split-char').forEach((char) => {
        index += 1;
        char.style.setProperty('--char', index);
      });
      group.querySelectorAll('[data-button-character]').forEach((iconChar) => {
        index += 1;
        iconChar.style.setProperty('--char', index);
      });
      if (index > maxChars) maxChars = index;
    });

    // Cap the total stagger sweep for long labels
    if (maxChars > CHAR_THRESHOLD) {
      const stagger = MAX_SWEEP / (maxChars - 1);
      element.style.setProperty('--button-099-stagger', stagger.toFixed(4) + 's');
    }
  });
}

initButton099();


